// Only the public wrong.invalid / proof.localhost fixture, after the original TLS error+wait rejection.
const FIXTURE_HOSTNAME_MESSAGE = "Hostname/IP does not match certificate's altnames: Host: wrong.invalid. is not in the cert's altnames: DNS:proof.localhost";
function fixtureHostnameRefusalCode(error:unknown, diagnostic:TlsDiagnostic|undefined):"ERR_TLS_CERT_ALTNAME_INVALID"|null {
  if (!diagnostic || diagnostic.schema!=="tls-refusal-diagnostic-v1" || diagnostic.phases!==99 ||
      diagnostic.ownCode!=="ABSENT" ||
      error===null || (typeof error!=="object" && typeof error!=="function")) return null;
  try {
    if (Object.getOwnPropertyDescriptor(error,"code")!==undefined) return null;
    const message=Object.getOwnPropertyDescriptor(error,"message");
    return message && Object.hasOwn(message,"value") && message.value===FIXTURE_HOSTNAME_MESSAGE
      ? "ERR_TLS_CERT_ALTNAME_INVALID" : null;
  } catch {return null;}
}
